[metadata] {"type": "create", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>State of Developer Ecosystem 2024 - Infographic</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;600;700&family=Inter:wght@300;400;500;600;700&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  :root {
    --bg-deep: #0a0e1a;
    --bg-card: #111827;
    --bg-card-hover: #1a2332;
    --border: #1e293b;
    --text-primary: #e2e8f0;
    --text-secondary: #94a3b8;
    --text-muted: #64748b;
    --accent-blue: #3b82f6;
    --accent-blue-glow: #60a5fa;
    --accent-amber: #f59e0b;
    --accent-amber-glow: #fbbf24;
    --accent-mint: #10b981;
    --accent-mint-glow: #34d399;
    --accent-red: #ef4444;
    --accent-purple: #8b5cf6;
    --accent-cyan: #06b6d4;
  }

  body {
    background: var(--bg-deep);
    color: var(--text-primary);
    font-family: 'Inter', -apple-system, sans-serif;
    width: 2384px;
    height: 3370px;
    overflow: hidden;
    padding: 80px 90px;
    position: relative;
  }

  /* Subtle grid background */
  body::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background-image:
      linear-gradient(rgba(59,130,246,0.03) 1px, transparent 1px),
      linear-gradient(90deg, rgba(59,130,246,0.03) 1px, transparent 1px);
    background-size: 60px 60px;
    pointer-events: none;
    z-index: 0;
  }

  .poster { position: relative; z-index: 1; }

  /* ---- HEADER ---- */
  .header {
    margin-bottom: 60px;
    border-bottom: 2px solid var(--border);
    padding-bottom: 40px;
  }

  .header-top {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 16px;
  }

  .header-badge {
    background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
    color: white;
    font-family: 'JetBrains Mono', monospace;
    font-size: 14px;
    font-weight: 600;
    padding: 6px 16px;
    border-radius: 4px;
    letter-spacing: 1.5px;
    text-transform: uppercase;
  }

  .header-survey {
    font-family: 'JetBrains Mono', monospace;
    font-size: 16px;
    color: var(--accent-amber);
    letter-spacing: 0.5px;
  }

  .header h1 {
    font-family: 'JetBrains Mono', monospace;
    font-size: 68px;
    font-weight: 700;
    line-height: 1.1;
    letter-spacing: -1px;
    margin-bottom: 12px;
    background: linear-gradient(135deg, #e2e8f0, #94a3b8);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .header .subtitle {
    font-size: 26px;
    color: var(--text-secondary);
    font-weight: 300;
    line-height: 1.4;
    max-width: 1600px;
  }

  .header .subtitle strong {
    color: var(--accent-blue-glow);
    font-weight: 500;
  }

  /* ---- KEY METRICS BAR ---- */
  .metrics-bar {
    display: flex;
    gap: 24px;
    margin-bottom: 56px;
  }

  .metric-card {
    flex: 1;
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 28px 24px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }

  .metric-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
  }

  .metric-card:nth-child(1)::before { background: var(--accent-blue); }
  .metric-card:nth-child(2)::before { background: var(--accent-amber); }
  .metric-card:nth-child(3)::before { background: var(--accent-mint); }
  .metric-card:nth-child(4)::before { background: var(--accent-purple); }

  .metric-value {
    font-family: 'JetBrains Mono', monospace;
    font-size: 44px;
    font-weight: 700;
    line-height: 1;
    margin-bottom: 8px;
  }

  .metric-card:nth-child(1) .metric-value { color: var(--accent-blue-glow); }
  .metric-card:nth-child(2) .metric-value { color: var(--accent-amber-glow); }
  .metric-card:nth-child(3) .metric-value { color: var(--accent-mint-glow); }
  .metric-card:nth-child(4) .metric-value { color: var(--accent-purple); }

  .metric-label {
    font-size: 14px;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 500;
  }

  /* ---- SECTION TITLES ---- */
  .section-title {
    font-family: 'JetBrains Mono', monospace;
    font-size: 30px;
    font-weight: 600;
    margin-bottom: 8px;
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .section-title .icon {
    width: 36px;
    height: 36px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 18px;
  }

  .section-subtitle {
    font-size: 17px;
    color: var(--text-secondary);
    margin-bottom: 32px;
    font-weight: 300;
  }

  /* ---- CENTERPIECE: LANGUAGE TRAJECTORY ---- */
  .centerpiece {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 48px;
    margin-bottom: 48px;
    position: relative;
    overflow: hidden;
  }

  .centerpiece::after {
    content: '';
    position: absolute;
    top: -50%;
    right: -20%;
    width: 600px;
    height: 600px;
    background: radial-gradient(circle, rgba(59,130,246,0.06) 0%, transparent 70%);
    pointer-events: none;
  }

  .chart-container {
    position: relative;
    z-index: 1;
  }

  .trajectory-svg {
    width: 100%;
    height: auto;
  }

  /* ---- TWO COLUMN LAYOUT ---- */
  .two-col {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 36px;
    margin-bottom: 48px;
  }

  .panel {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 40px;
  }

  /* ---- PROMISE INDEX ---- */
  .promise-row {
    display: flex;
    align-items: center;
    padding: 16px 0;
    border-bottom: 1px solid rgba(30,41,59,0.6);
  }

  .promise-row:last-child { border-bottom: none; }

  .promise-rank {
    font-family: 'JetBrains Mono', monospace;
    font-size: 22px;
    font-weight: 700;
    width: 48px;
    color: var(--text-muted);
  }

  .promise-rank.top { color: var(--accent-amber-glow); }

  .promise-lang {
    font-family: 'JetBrains Mono', monospace;
    font-size: 20px;
    font-weight: 600;
    width: 140px;
  }

  .promise-bar-container {
    flex: 1;
    height: 32px;
    background: rgba(30,41,59,0.6);
    border-radius: 6px;
    overflow: hidden;
    margin: 0 20px;
    position: relative;
  }

  .promise-bar {
    height: 100%;
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    padding-right: 12px;
    transition: width 0.5s ease;
  }

  .promise-score {
    font-family: 'JetBrains Mono', monospace;
    font-size: 18px;
    font-weight: 700;
    min-width: 48px;
    text-align: right;
  }

  .promise-bar.ts { background: linear-gradient(90deg, #3b82f6, #60a5fa); }
  .promise-bar.rust { background: linear-gradient(90deg, #f59e0b, #fbbf24); }
  .promise-bar.python { background: linear-gradient(90deg, #10b981, #34d399); }
  .promise-bar.go { background: linear-gradient(90deg, #06b6d4, #22d3ee); }
  .promise-bar.lua { background: linear-gradient(90deg, #8b5cf6, #a78bfa); }
  .promise-bar.cpp { background: linear-gradient(90deg, #64748b, #94a3b8); }
  .promise-bar.kotlin { background: linear-gradient(90deg, #8b5cf6, #c084fc); }

  .promise-bar.ts .promise-score,
  .promise-bar.rust .promise-score { color: #0a0e1a; }

  /* ---- DATABASE SECTION ---- */
  .db-row {
    display: flex;
    align-items: center;
    padding: 14px 0;
    border-bottom: 1px solid rgba(30,41,59,0.6);
  }

  .db-row:last-child { border-bottom: none; }

  .db-name {
    font-family: 'JetBrains Mono', monospace;
    font-size: 17px;
    font-weight: 500;
    width: 130px;
  }

  .db-bars {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 4px;
  }

  .db-bar-track {
    height: 22px;
    background: rgba(30,41,59,0.6);
    border-radius: 4px;
    overflow: hidden;
    position: relative;
  }

  .db-bar-fill {
    height: 100%;
    border-radius: 4px;
    position: relative;
  }

  .db-bar-label {
    position: absolute;
    right: 8px;
    top: 50%;
    transform: translateY(-50%);
    font-family: 'JetBrains Mono', monospace;
    font-size: 12px;
    font-weight: 600;
  }

  /* ---- CLOUD ---- */
  .cloud-row {
    display: flex;
    align-items: center;
    padding: 14px 0;
    border-bottom: 1px solid rgba(30,41,59,0.6);
  }

  .cloud-row:last-child { border-bottom: none; }

  .cloud-provider {
    font-family: 'JetBrains Mono', monospace;
    font-size: 18px;
    font-weight: 600;
    width: 170px;
  }

  .cloud-bar-track {
    flex: 1;
    height: 36px;
    background: rgba(30,41,59,0.6);
    border-radius: 6px;
    overflow: hidden;
    margin-right: 16px;
  }

  .cloud-bar-fill {
    height: 100%;
    border-radius: 6px;
    display: flex;
    align-items: center;
    padding-left: 16px;
    font-family: 'JetBrains Mono', monospace;
    font-size: 16px;
    font-weight: 700;
  }

  /* ---- PLATFORMS ---- */
  .platforms-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
  }

  .platform-card {
    background: rgba(30,41,59,0.4);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 24px;
    text-align: center;
  }

  .platform-pct {
    font-family: 'JetBrains Mono', monospace;
    font-size: 40px;
    font-weight: 700;
    line-height: 1;
    margin-bottom: 8px;
  }

  .platform-name {
    font-size: 15px;
    color: var(--text-secondary);
    font-weight: 400;
  }

  /* ---- AI SECTION ---- */
  .ai-section {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 40px;
    margin-bottom: 48px;
    position: relative;
    overflow: hidden;
  }

  .ai-section::after {
    content: '';
    position: absolute;
    bottom: -30%;
    left: -10%;
    width: 400px;
    height: 400px;
    background: radial-gradient(circle, rgba(139,92,246,0.08) 0%, transparent 70%);
    pointer-events: none;
  }

  .ai-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 48px;
    position: relative;
    z-index: 1;
  }

  .ai-hero {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
  }

  .ai-big-number {
    font-family: 'JetBrains Mono', monospace;
    font-size: 120px;
    font-weight: 700;
    line-height: 1;
    background: linear-gradient(135deg, var(--accent-purple), var(--accent-cyan));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 8px;
  }

  .ai-big-label {
    font-size: 20px;
    color: var(--text-secondary);
    font-weight: 400;
    margin-bottom: 16px;
  }

  .ai-detail-list {
    display: flex;
    flex-direction: column;
    gap: 20px;
    justify-content: center;
  }

  .ai-detail-item {
    display: flex;
    align-items: center;
    gap: 16px;
  }

  .ai-detail-icon {
    width: 48px;
    height: 48px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 22px;
    flex-shrink: 0;
  }

  .ai-detail-text h4 {
    font-family: 'JetBrains Mono', monospace;
    font-size: 18px;
    font-weight: 600;
    margin-bottom: 4px;
  }

  .ai-detail-text p {
    font-size: 15px;
    color: var(--text-secondary);
    line-height: 1.4;
  }

  /* ---- DOCKER ---- */
  .docker-strip {
    background: linear-gradient(135deg, rgba(6,182,212,0.1), rgba(59,130,246,0.1));
    border: 1px solid rgba(6,182,212,0.2);
    border-radius: 12px;
    padding: 24px 40px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 48px;
  }

  .docker-left {
    display: flex;
    align-items: center;
    gap: 16px;
  }

  .docker-icon-box {
    width: 52px;
    height: 52px;
    background: rgba(6,182,212,0.15);
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 26px;
  }

  .docker-value {
    font-family: 'JetBrains Mono', monospace;
    font-size: 42px;
    font-weight: 700;
    color: var(--accent-cyan);
  }

  .docker-label {
    font-size: 18px;
    color: var(--text-secondary);
  }

  /* ---- FOOTER ---- */
  .footer {
    border-top: 1px solid var(--border);
    padding-top: 24px;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  .footer-left {
    font-size: 14px;
    color: var(--text-muted);
    line-height: 1.6;
  }

  .footer-right {
    font-family: 'JetBrains Mono', monospace;
    font-size: 13px;
    color: var(--text-muted);
    text-align: right;
  }

  /* ---- SVG CHART STYLES ---- */
  .chart-legend {
    display: flex;
    gap: 28px;
    margin-top: 24px;
    justify-content: center;
    flex-wrap: wrap;
  }

  .legend-item {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 15px;
    color: var(--text-secondary);
  }

  .legend-dot {
    width: 12px;
    height: 12px;
    border-radius: 50%;
  }

  .legend-item strong {
    color: var(--text-primary);
    font-weight: 600;
  }

  /* ---- TS CALLOUT ---- */
  .ts-callout {
    background: linear-gradient(135deg, rgba(59,130,246,0.12), rgba(139,92,246,0.08));
    border: 1px solid rgba(59,130,246,0.25);
    border-radius: 12px;
    padding: 28px 32px;
    margin-top: 28px;
    display: flex;
    align-items: center;
    gap: 24px;
  }

  .ts-callout-score {
    font-family: 'JetBrains Mono', monospace;
    font-size: 56px;
    font-weight: 700;
    color: var(--accent-blue-glow);
    line-height: 1;
  }

  .ts-callout-text h3 {
    font-family: 'JetBrains Mono', monospace;
    font-size: 20px;
    font-weight: 600;
    margin-bottom: 4px;
    color: var(--accent-blue-glow);
  }

  .ts-callout-text p {
    font-size: 16px;
    color: var(--text-secondary);
    line-height: 1.5;
  }

  /* ---- TYPE annotation ---- */
  .annotation {
    font-size: 14px;
    color: var(--text-muted);
    font-style: italic;
    margin-top: 8px;
  }

  /* Insight tags */
  .insight-tag {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: rgba(16,185,129,0.1);
    border: 1px solid rgba(16,185,129,0.25);
    border-radius: 20px;
    padding: 4px 14px;
    font-size: 13px;
    font-weight: 500;
    color: var(--accent-mint-glow);
  }

  .insight-tag.amber {
    background: rgba(245,158,11,0.1);
    border-color: rgba(245,158,11,0.25);
    color: var(--accent-amber-glow);
  }

  .insight-tag.blue {
    background: rgba(59,130,246,0.1);
    border-color: rgba(59,130,246,0.25);
    color: var(--accent-blue-glow);
